<script setup lang="ts">
import type { DraftPurchaseReturnV1 } from '~/types/purchase-return'
import { displayDecimal } from '~/utils/catalog'
import { formatCreatedAt } from '~/utils/material'
const data = defineModel<DraftPurchaseReturnV1>({ required: true })
const props = defineProps<{ disabled: boolean; prefix?: string; field?: string; errors?: Record<string, string> }>()
const prefix = computed(() => props.prefix ?? 'purchase-return'), field = computed(() => props.field ? `${props.field}.` : '')
const { choices, source, holding, checking, failure, select, load, loadChoices } = usePurchaseReturnSource(data, toRef(props, 'disabled'))
const sourceVersion = computed(() => source.value?.current?.reference.kind === 'existing' ? source.value.current.reference.version_id : null)
</script>
<template>
  <div class="purchase-return-fields">
    <div class="field"><label :for="`${prefix}-receipt`">반품할 원입고</label><select :id="`${prefix}-receipt`" :data-field="`${field}receipt_id`" :value="data.receipt_id ?? ''" :disabled="disabled" :aria-invalid="!!errors?.receipt_id" @change="select(($event.target as HTMLSelectElement).value)"><option value="">원입고 선택</option><option v-if="data.receipt_id && !choices.some(item => item.id === data.receipt_id)" :value="data.receipt_id">선택한 원입고 · {{ data.receipt_id.slice(0, 8) }}</option><option v-for="item in choices" :key="item.id" :value="item.id">{{ item.material_name }} · {{ item.receipt_date }} · {{ displayDecimal(item.quantity) }}{{ item.unit }} · {{ item.id.slice(0, 8) }}</option></select><p class="field-error">{{ errors?.receipt_id }}</p></div>
    <p v-if="failure" class="notice warning" role="alert">{{ failure }} <button class="text-button" type="button" :disabled="disabled" @click="loadChoices(); load()">원입고 다시 확인</button></p>
    <p v-if="checking" class="stale-note" role="status">원입고와 보유 근거를 확인하고 있습니다.</p>
    <section v-if="source" class="return-source-context" aria-label="반품 원입고 근거"><h3>원입고 근거</h3><NuxtLink :to="`/receipts/${source.original.id}`">원입고 기록 보기</NuxtLink><dl class="return-fields"><div><dt>원구입 참고 수량·금액</dt><dd>{{ displayDecimal(source.original.quantity) }}{{ source.original.unit }} · {{ displayDecimal(source.original.amount) }}원</dd></div><template v-if="source.current"><div><dt>유효 입고</dt><dd>{{ source.current.material_name }} · {{ displayDecimal(source.current.quantity) }}{{ source.current.unit }} · {{ displayDecimal(source.current.amount) }}원</dd></div><div><dt>이미 반품한 수량</dt><dd>{{ displayDecimal(source.current.returned_quantity) }}{{ source.current.unit }}</dd></div><div><dt>원입고 반환 가능 수량</dt><dd>{{ displayDecimal(source.current.remaining_quantity) }}{{ source.current.unit }}</dd></div></template></dl><p v-if="!source.current" class="notice warning">이 원입고의 유효 효과가 취소되었습니다. 원문과 미확인 요청을 보존했습니다. 새 반품은 유효한 원입고를 명시적으로 선택해야 합니다.</p><p v-else-if="sourceVersion !== data.expected_receipt_version_id" class="notice warning">선택한 입고 버전과 현재 버전이 다릅니다. 입력을 유지했습니다. 현재 입고 내용을 비교하고 적용해 주세요.</p><p class="field-hint">원구입 금액은 참고 근거입니다. 실제 차감액은 확정할 때의 평균 가치로 계산합니다. 입고일 {{ source.original.receipt_date }} · {{ formatCreatedAt(source.original.recorded_at) }} 기록</p><NuxtLink :to="{ path: '/purchase-returns', query: { receipt: source.original.id } }">이 원입고의 반품 기록</NuxtLink></section>
    <button v-if="data.receipt_id" class="text-button" type="button" :data-field="`${field}expected_receipt_version_id`" :disabled="disabled || checking" @click="load(true)">현재 원입고 정보 적용</button><p class="field-error">{{ errors?.expected_receipt_version_id }}</p>
    <section v-if="holding" class="stock-context" aria-label="반품 전 보유 근거"><p>현재 정산 기준: {{ holding.settlement_basis ? `${displayDecimal(holding.settlement_basis.quantity)}${holding.unit} · ${holding.settlement_basis.value === null ? '가치 미확인' : displayDecimal(holding.settlement_basis.value) + '원'}` : '아직 정산 기준 없음' }}</p><p class="field-hint">원입고 반환 한도와 현재 보유 수량을 각각 확인합니다. 이 조회는 확정 금액이 아니며 미리보기에서 다시 확인합니다.</p><NuxtLink :to="`/materials/${holding.material_id}`">품목의 보유 근거 보기</NuxtLink></section>
    <div class="quantity-fields"><div class="field"><label :for="`${prefix}-quantity`">실제 반품 수량</label><input :id="`${prefix}-quantity`" v-model="data.quantity" :data-field="`${field}quantity`" inputmode="decimal" :disabled="disabled" :aria-invalid="!!errors?.quantity"><p class="field-error">{{ errors?.quantity }}</p></div><div class="field"><label :for="`${prefix}-unit`">반품 단위</label><input :id="`${prefix}-unit`" v-model="data.unit" :data-field="`${field}unit`" :disabled="disabled" :aria-invalid="!!errors?.unit"><p class="field-error">{{ errors?.unit }}</p></div></div>
    <div class="field"><label :for="`${prefix}-note`">반품 메모 (선택)</label><textarea :id="`${prefix}-note`" v-model="data.note" :data-field="`${field}note`" rows="3" :disabled="disabled"/><p class="field-error">{{ errors?.note }}</p></div><p class="field-hint">실제로 반환한 수량을 입력하세요. 환급액을 추정하거나 수량을 자동으로 줄이지 않습니다.</p>
  </div>
</template>
